@startuml

class School {
  + name : string
}

class Teacher {
  + firstName : string
  + lastName : string
  + email : string
}

class Student {
  + firstName : string
  + lastName : string
}

class TeachingAssignment {
  + hours : int
}

class Room {
  + name : string
}

class Classroom extends Room {
  + capacity : int
}

class Gym extends Room {
  + size : float
}

class ClassGroup {
  + name : string
}

School "1" -- "1" Teacher : principal
School "1" -- "1..*" Teacher : employs
Teacher "1..3" -- "0..*" School : teaches
Teacher "1" -- "0..*" TeachingAssignment
School "1" -- "0..*" TeachingAssignment
TeachingAssignment "0..*" -- "1" School

Student "1" -- "1" ClassGroup : belongs to
ClassGroup "1" -- "1" Classroom : assigned to
Classroom "1" -- "0..*" ClassGroup : contains

@enduml

